// Duplicate row in the real app, on every engine: right-click a row → Duplicate row (or Ctrl+D) → a new
// pending row with the same values and an empty primary key, the key cell open for editing; type a
// key and a new name, save, and the table has a copy equal to the original but for those two values.
// Also: double-clicking a row number does nothing; an auto-generated key left empty is filled in by the
// database; Undo removes the copy; the row menu has no Undo / Redo (keyboard only); a ClickHouse grid
// (read-only) has no Duplicate row.
// Run: npx electron test/smoke-duplicate.js [oracle|postgres|mysql|sqlite|clickhouse ...]
// Servers from test/docker (docker compose -f test/docker/docker-compose.yml up -d); an engine whose
// server does not answer is skipped.
const path = require('path');
const fs = require('fs');
const os = require('os');
const { app, webContents } = require('electron');
const db = require('../src/main/db');
const { ENGINES } = require('./fixtures/copy-engines');

app.setPath('userData', path.join(app.getPath('temp'), 'lookup-smoke-duplicate'));
fs.rmSync(app.getPath('userData'), { recursive: true, force: true });
require('../src/main/main.js');

const wait = (ms) => new Promise((r) => setTimeout(r, ms));
// A table whose key the database fills in, per engine.
const AUTO = {
  oracle: { drop: 'BEGIN EXECUTE IMMEDIATE \'DROP TABLE COPY_AUTO PURGE\'; EXCEPTION WHEN OTHERS THEN NULL; END;', create: 'CREATE TABLE COPY_AUTO (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NAME VARCHAR2(40))', insert: 'INSERT INTO COPY_AUTO (NAME) VALUES (\'first\')' },
  postgres: { create: 'CREATE TABLE lookup_copy.copy_auto (id int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text)', insert: 'INSERT INTO lookup_copy.copy_auto (name) VALUES (\'first\')' },
  mysql: { create: 'CREATE TABLE lookup_copy.copy_auto (id int AUTO_INCREMENT PRIMARY KEY, name varchar(40))', insert: 'INSERT INTO lookup_copy.copy_auto (name) VALUES (\'first\')' },
  sqlite: { drop: 'DROP TABLE IF EXISTS copy_auto', create: 'CREATE TABLE copy_auto (id INTEGER PRIMARY KEY, name text)', insert: 'INSERT INTO copy_auto (name) VALUES (\'first\')' },
};

/** In the window: a real DataGrid on the table's data; right-click row `row` → Duplicate row, type into
 *  the cells that open (key first, then the name cell double-clicked), and save. */
const DUPLICATE = (e, table, edits) => `(async () => {
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  const key = ${JSON.stringify(e.key)};
  const d = await api.tableData({ owner: ${JSON.stringify(e.owner)}, name: ${JSON.stringify(table)}, type: 'TABLE', offset: 0, limit: 50, sort: { col: key, dir: 'asc' } });
  document.querySelectorAll('.dup-host').forEach((x) => x.remove());
  const host = document.createElement('div');
  host.className = 'dup-host';
  host.style.cssText = 'position:fixed;inset:0;z-index:9999;display:flex;background:#fff';
  document.body.append(host);
  const g = new window.DataGrid({ columns: d.columns, rows: d.rows, rowids: d.rowids, editable: d.editable, keyColumns: d.keyColumns });
  g.el.style.flex = '1';
  host.append(g.el);
  g.paint();
  await wait(100);
  const out = { editable: d.editable, keyColumns: d.keyColumns, before: g.total, steps: [] };
  const type = async (text, col) => {
    const input = g.el.querySelector('.cell-edit');
    if (!input) throw new Error('no cell editor open');
    out.steps.push({ opened: col, had: input.value });
    input.value = text;
    input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
    await wait(50);
  };
  const menu = (vi) => {
    const td = g.tbody.querySelector('tr[data-vi="' + vi + '"] td.rn');
    td.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, button: 2 }));
    td.dispatchEvent(new MouseEvent('contextmenu', { bubbles: true, cancelable: true, clientX: 60, clientY: 60 }));
    return [...document.querySelectorAll('.ctx .ctx-item')];
  };
  const closeMenu = () => document.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
  // Double-clicking a row number no longer duplicates.
  g.tbody.querySelector('tr[data-vi="0"] td.rn').dispatchEvent(new MouseEvent('dblclick', { bubbles: true }));
  await wait(100);
  out.afterDblclick = g.total;
  for (const ed of ${JSON.stringify(edits)}) {
    const items = menu(ed.row);
    const item = items.find((x) => x.textContent.trim().startsWith('Duplicate row'));
    out.menuHasDuplicate = !!item;
    if (item) out.duplicateHint = item.textContent.trim();
    if (!item || !d.editable) {
      closeMenu();
      // Ctrl+D on a read-only grid adds nothing either.
      g.el.dispatchEvent(new KeyboardEvent('keydown', { key: 'd', ctrlKey: true, bubbles: true }));
      await wait(100);
      out.after = g.total; return out;
    }
    if (ed.ctrlD) {
      closeMenu();
      g.setSelection({ r: ed.row, c: 2 }, { r: ed.row, c: 2 }); // a cell of that row has the focus
      g.el.focus();
      g.el.dispatchEvent(new KeyboardEvent('keydown', { key: 'd', ctrlKey: true, bubbles: true, cancelable: true }));
    } else item.click();
    await wait(150);
    const vi = g.total - 1;
    g.el.scrollTop = g.el.scrollHeight; g.paint(); await wait(50);
    if (ed.key !== undefined) await type(ed.key, g.columns[g.sel.c].name); else { const i = g.el.querySelector('.cell-edit'); out.steps.push({ opened: g.columns[g.sel.c].name, had: i && i.value }); i && i.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await wait(50); }
    if (ed.name !== undefined) {
      const nc = g.columns.findIndex((c) => /^name$/i.test(c.name));
      g.tbody.querySelector('tr[data-vi="' + vi + '"] td[data-c="' + nc + '"]').dispatchEvent(new MouseEvent('dblclick', { bubbles: true }));
      await wait(50);
      await type(ed.name, g.columns[nc].name);
    }
  }
  out.after = g.total;
  // Undo steps back through the typed key, then the last duplicate; Redo brings both back.
  out.menuUndoRedo = menu(0).map((x) => x.textContent.trim()).filter((t) => /^(Undo|Redo)/.test(t));
  closeMenu();
  out.undoLabels = [g.undo(), g.undo()]; out.afterUndo = g.total;
  out.menuUndoRedo.push(...menu(0).map((x) => x.textContent.trim()).filter((t) => /^(Undo|Redo)/.test(t)));
  closeMenu();
  g.redo(); g.redo(); out.afterRedo = g.total;
  const changes = g.getChanges();
  out.inserts = changes.inserts.length;
  out.preview = await api.previewChanges({ owner: ${JSON.stringify(e.owner)}, name: ${JSON.stringify(table)}, changes });
  await api.applyChanges({ owner: ${JSON.stringify(e.owner)}, name: ${JSON.stringify(table)}, changes });
  await api.commit().catch(() => {});
  const r = await api.tableData({ owner: ${JSON.stringify(e.owner)}, name: ${JSON.stringify(table)}, type: 'TABLE', offset: 0, limit: 50, sort: { col: key, dir: 'asc' } });
  out.columns = r.columns.map((c) => c.name);
  out.rows = r.rows;
  host.remove();
  return out;
})()`;

let passed = 0;
const failures = [];
const check = (id, name, ok, detail) => {
  if (ok) { passed++; console.log('  ok  ', name); } else { failures.push(`${id}: ${name}`); console.log('  FAIL', name, detail !== undefined ? '\n    ' + JSON.stringify(detail).slice(0, 600) : ''); }
};

app.on('browser-window-created', (_e, win) => {
  win.webContents.once('did-finish-load', async () => {
    let code = 0;
    try {
      await wait(1500);
      const view = webContents.getAllWebContents().find((w) => w.getURL().includes('index.html'));
      const run = (js) => view.executeJavaScript(js);
      const pick = process.argv.slice(2).filter((a) => ENGINES[a]);
      let w = 9000;
      for (const id of pick.length ? pick : Object.keys(ENGINES)) {
        const e = { ...ENGINES[id], key: id === 'oracle' ? 'ID' : 'id' };
        const prep = ++w; // the tables are made on a separate session in this process
        let tmp = null;
        if (id === 'sqlite') {
          tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'lookup-dup-'));
          e.cfg = { engine: 'sqlite', file: path.join(tmp, 'dup.db'), autoCommit: true };
          fs.writeFileSync(e.cfg.file, '');
        }
        try { await db.connect(prep, e.cfg); } catch (err) { console.log(`${id}: skipped (${err.message.split('\n')[0]})`); continue; }
        console.log(id);
        const exec = async (sqls) => { const r = await db.run(prep, sqls, { maxRows: 0 }); const er = r.find((x) => x.kind === 'error'); if (er) throw new Error(er.message + ' in ' + er.sql); };
        try {
          if (e.setup) await exec(e.setup);
          if (e.drop) await exec([e.drop(e.src)]);
          await exec([e.create(e.src), ...e.rows]);
          const a = AUTO[id];
          if (a) await exec([...(a.drop ? [a.drop] : []), a.create, a.insert]);
          await db.disconnect(prep);
          // Connect the window the way the app does: a saved connection (manual commit, Lookup's default).
          const saved = await run(`api.saveConnection(${JSON.stringify({ ...e.cfg, name: 'dup-' + id, autoCommit: false })})`);
          await run(`api.connect(${JSON.stringify(saved.id || saved)}, ${JSON.stringify(e.cfg.password || '')})`);

          const src = await run(`api.tableData({ owner: ${JSON.stringify(e.owner)}, name: ${JSON.stringify(e.src)}, type: 'TABLE', offset: 0, limit: 50, sort: { col: ${JSON.stringify(e.key)}, dir: 'asc' } })`);
          // Row 1: binary, quotes, & and backslash; row 2: a newline and a long text. New keys typed; row 1 renamed.
          const r = await run(DUPLICATE(e, e.src, [{ row: 0, key: '777', name: 'Copy of row 1' }, { row: 1, key: '778', ctrlD: true }]));
          if (id === 'clickhouse') {
            check(id, 'read-only grid: no Duplicate row in the menu, nothing added', r.editable === false && !r.menuHasDuplicate && r.after === r.before && r.afterDblclick === r.before, r);
          } else {
            const ki = r.columns.indexOf(e.key);
            const ni = r.columns.findIndex((c) => /^name$/i.test(c));
            check(id, 'the menu item shows Ctrl+D', /Ctrl\+D$/.test(r.duplicateHint || ''), r.duplicateHint);
            check(id, 'the key column is reported and opens first, empty', JSON.stringify(r.keyColumns) === JSON.stringify([e.key]) && r.steps[0].opened === e.key && r.steps[0].had === '', r.steps);
            check(id, 'double-clicking a row number adds nothing', r.afterDblclick === r.before, r);
            check(id, 'right-click → Duplicate row and Ctrl+D each add one pending row; Undo / Redo', r.after === r.before + 2 && r.afterUndo === r.before + 1 && r.afterRedo === r.before + 2
              && r.undoLabels[0] === 'edit ' + e.key && r.undoLabels[1] === 'duplicate row', r);
            check(id, 'the row menu has no Undo or Redo (Ctrl+Z / Ctrl+Shift+Z only)', r.menuUndoRedo.length === 0, r.menuUndoRedo);
            check(id, 'two INSERTs, previewed and saved', r.inserts === 2 && /INSERT/i.test(r.preview), r.preview);
            const byKey = (k) => r.rows.find((x) => String(x[ki]) === k);
            const d1 = byKey('777');
            const d2 = byKey('778');
            const same = (dup, orig, skip) => dup && orig.every((v, c) => skip.includes(c) || JSON.stringify(v) === JSON.stringify(dup[c]));
            check(id, 'the copy of row 1 has every value of the original, with the typed key and name', same(d1, src.rows[0], [ki, ni]) && d1[ni] === 'Copy of row 1', { dup: d1, orig: src.rows[0] });
            check(id, 'the copy of row 2 (newline, long text) has every value of the original but the key', same(d2, src.rows[1], [ki]), { dup: d2, orig: src.rows[1] });
            check(id, 'the originals are unchanged', r.rows.length === 5 && same(r.rows[0], src.rows[0], []) && same(r.rows[1], src.rows[1], []));
            if (AUTO[id]) {
              const auto = await run(DUPLICATE(e, id === 'oracle' ? 'COPY_AUTO' : 'copy_auto', [{ row: 0 }]));
              const ids = auto.rows.map((x) => String(x[0]));
              check(id, 'an auto-generated key left empty is filled in by the database', auto.rows.length === 2 && new Set(ids).size === 2 && auto.rows[1][1] === 'first', auto.rows);
            }
          }
          await run('api.disconnect()');
        } catch (err) {
          failures.push(`${id}: ${err.message}`);
          console.log('  FAIL', err.message);
        } finally {
          await db.connect(prep, e.cfg).then(() => db.run(prep, [
            ...(e.setup ? [e.setup[0]] : []), ...(e.drop ? [e.drop(e.src)] : []), ...(AUTO[id] && AUTO[id].drop ? [AUTO[id].drop] : [])])).catch(() => {});
          await db.disconnect(prep).catch(() => {});
          if (tmp) fs.rmSync(tmp, { recursive: true, force: true });
        }
      }
      console.log(`\n${passed} passed, ${failures.length} failed`);
      if (failures.length) { console.log(failures.map((f) => '  - ' + f).join('\n')); code = 1; }
    } catch (err) {
      console.log('SMOKE ERROR', err.stack);
      code = 1;
    }
    app.exit(code);
  });
});
